const int buttonPin = 2;     // Pin connected to the push button
const int ledPin = 13;       // Pin connected to the LED

int ledState = LOW;          // Current state of the LED
int buttonState = HIGH;      // Current debounced button state
int lastButtonState = HIGH;  // Previous raw reading from the button pin
int reading;                 // Current raw reading from the button pin

unsigned long lastDebounceTime = 0;  // Last time the button state changed
unsigned long debounceDelay = 50;    // Debounce time in milliseconds

void setup() {
  pinMode(buttonPin, INPUT_PULLUP); // Enable internal pull-up resistor
  pinMode(ledPin, OUTPUT);
  digitalWrite(ledPin, ledState);   // Set initial LED state
}

void loop() {
  // Read the current state of the button
  reading = digitalRead(buttonPin);

  // If the button state has changed, reset the debounce timer
  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }

  // If the button state has been stable for longer than the debounce delay
  if ((millis() - lastDebounceTime) > debounceDelay) {
    // If the button state has actually changed after debounce
    if (reading != buttonState) {
      buttonState = reading;

      // If the button is pressed (LOW because of INPUT_PULLUP)
      if (buttonState == LOW) {
        ledState = !ledState;          // Toggle LED state
        digitalWrite(ledPin, ledState); // Update LED pin
      }
    }
  }

  // Save the raw reading for next loop iteration
  lastButtonState = reading;
}
```

